static int failures = 0;

#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::printf("FAIL  %s:%d  %s\n", __FILE__, __LINE__, #cond);     \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

static std::uintptr_t addr(const void* p) { return reinterpret_cast<std::uintptr_t>(p); }

// A pointer value that does not point to a slot. Never dereferenced.
template <typename T>
static T* at_offset(const T* p, std::ptrdiff_t bytes){
    return reinterpret_cast<T*>(const_cast<std::byte*>(reinterpret_cast<const std::byte*>(p)) + bytes);
}

// Allocate every free slot, return them sorted by address, then give them all back.
template <typename T, std::size_t N>
static std::vector<T*> all_slots(Pool<T, N>& pool){
    std::vector<T*> v;
    while (T* p = pool.allocate())
        v.push_back(p);
    for (T* p : v)
        pool.release(p);
    std::sort(v.begin(), v.end(), [](T* a, T* b){ return addr(a) < addr(b); });
    return v;
}

// Number of free slots, leaving the pool as it was.
template <typename T, std::size_t N>
static std::size_t free_slots(Pool<T, N>& pool){
    return all_slots(pool).size();
}

#ifndef NDEBUG
// Runs f in a child process; true if the child died from an assert (SIGABRT).
template <typename F>
static bool aborts(F f){
    std::fflush(stdout);
    const pid_t pid = fork();
    if (pid == 0){
        prctl(PR_SET_DUMPABLE, 0);                        // no core dump: apport takes ~1 s per abort
        const int devnull = open("/dev/null", O_WRONLY);  // hide the assert message
        dup2(devnull, STDERR_FILENO);
        f();
        _exit(0);                                         // returned: the assert did not fire
    }
    int status = 0;
    waitpid(pid, &status, 0);
    return WIFSIGNALED(status) && WTERMSIG(status) == SIGABRT;
}
#endif

// A bad release: aborts with asserts on, changes nothing with NDEBUG.
#ifndef NDEBUG
#define EXPECT_REJECTED(pool, ptr)                                           \
    CHECK(aborts([&]{ (pool).release(ptr); }))
#else
#define EXPECT_REJECTED(pool, ptr)                                           \
    do {                                                                     \
        const std::size_t before_ = free_slots(pool);                        \
        (pool).release(ptr);                                                 \
        CHECK(free_slots(pool) == before_);                                  \
    } while (0)
#endif

// ---------------------------------------------------------------------------
// 1. Allocation
// ---------------------------------------------------------------------------

static void fill_and_drain(){
    Pool<Tick, 8> pool;
    std::vector<Tick*> got;
    for (int i = 0; i < 8; ++i){
        Tick* t = pool.allocate(Tick{i, 100 + i, 1, 0, Operation::execute, false});
        CHECK(t != nullptr);
        got.push_back(t);
    }
    CHECK(pool.allocate() == nullptr);                    // full
    CHECK(pool.allocate() == nullptr);                    // still full

    std::set<Tick*> distinct(got.begin(), got.end());
    CHECK(distinct.size() == 8);
    for (int i = 0; i < 8; ++i)                           // no slot overwrote another
        CHECK(got[i]->ts_ns == i && got[i]->price == 100 + i);

    for (Tick* t : got)
        pool.release(t);
    CHECK(free_slots(pool) == 8);
}

static void reuse_after_release(){
    Pool<Tick, 4> pool;
    Tick* a = pool.allocate();
    pool.release(a);
    Tick* b = pool.allocate();
    CHECK(b == a);                                        // LIFO: the slot just freed comes back first
    pool.release(b);
}

static void single_slot(){
    Pool<Tick, 1> pool;
    for (int i = 0; i < 5; ++i){
        Tick* t = pool.allocate();
        CHECK(t != nullptr);
        CHECK(pool.allocate() == nullptr);
        pool.release(t);
    }
    CHECK(free_slots(pool) == 1);
}

// The helpers above call allocate() with no arguments, so test types need a default constructor.
struct Pair{
    int a;
    double b;
    Pair() : a(0), b(0) {}
    Pair(int x, double y) : a(x), b(y) {}
};

static void forwards_constructor_args(){
    Pool<Pair, 2> pool;
    Pair* p = pool.allocate(7, 2.5);
    CHECK(p && p->a == 7 && p->b == 2.5);
    pool.release(p);
}

// Trivially copyable, but its constructor can throw.
struct Throwing{
    int v;
    Throwing() : v(0) {}
    explicit Throwing(int x) : v(x) { if (x < 0) throw x; }
};

static void throwing_constructor_keeps_slot(){
    Pool<Throwing, 2> pool;
    bool threw = false;
    try { (void)pool.allocate(-1); } catch (int) { threw = true; }
    CHECK(threw);
    CHECK(free_slots(pool) == 2);                         // the slot was not lost
}

// The production size. With asserts on, each release() scans the free list (O(n)), so the
// debug build uses a smaller pool to keep the whole test in about a second.
#ifdef NDEBUG
constexpr std::size_t kLarge = 65536;
#else
constexpr std::size_t kLarge = 4096;
#endif

static void large_pool(){
    Pool<Tick, kLarge> pool;
    std::vector<Tick*> v;
    v.reserve(kLarge);
    while (Tick* t = pool.allocate())
        v.push_back(t);
    CHECK(v.size() == kLarge);
    for (Tick* t : v)
        pool.release(t);
    CHECK(free_slots(pool) == kLarge);
}

// Random allocate/release against a set of live pointers.
static void random_against_model(){
    Pool<Tick, 64> pool;
    std::set<Tick*> live;
    std::vector<Tick*> order;
    std::mt19937 rng(12345);
    for (int step = 0; step < 100'000; ++step){
        if (rng() % 2 == 0){
            Tick* t = pool.allocate();
            CHECK((t != nullptr) == (live.size() < 64));
            if (t){
                CHECK(!live.contains(t));                 // never hands out a live slot
                live.insert(t);
                order.push_back(t);
            }
        } else if (!order.empty()){
            const std::size_t i = rng() % order.size();
            Tick* t = order[i];
            order[i] = order.back();
            order.pop_back();
            live.erase(t);
            pool.release(t);
        }
    }
    CHECK(free_slots(pool) == 64 - live.size());
    for (Tick* t : order)
        pool.release(t);
    CHECK(free_slots(pool) == 64);
}

// ---------------------------------------------------------------------------
// 2. Release edge cases
// ---------------------------------------------------------------------------

static void release_first_and_last_slot(){
    Pool<Tick, 8> pool;
    const auto slots = all_slots(pool);
    std::vector<Tick*> held;
    while (Tick* t = pool.allocate())
        held.push_back(t);

    pool.release(slots.front());                          // lowest address: accepted
    pool.release(slots.back());                           // highest address: accepted
    CHECK(free_slots(pool) == 2);

    for (Tick* t : held)
        if (t != slots.front() && t != slots.back())
            pool.release(t);
    CHECK(free_slots(pool) == 8);
}

static void release_nullptr(){
    Pool<Tick, 4> pool;
    Tick* held = pool.allocate();                         // so the pool is not full
    EXPECT_REJECTED(pool, static_cast<Tick*>(nullptr));
    pool.release(held);
}

static void release_when_nothing_allocated(){
    // Every slot is already free: any release would push past capacity.
    Pool<Tick, 4> pool;
    Tick* t = pool.allocate();
    pool.release(t);
    EXPECT_REJECTED(pool, t);                             // also a double release
}

static void double_release(){
    Pool<Tick, 4> pool;
    Tick* a = pool.allocate();
    Tick* b = pool.allocate();                            // keeps the pool from being full
    pool.release(a);
#ifndef NDEBUG
    CHECK(aborts([&]{ pool.release(a); }));
#else
    // Not detected with NDEBUG: the duplicate check is an assert only. Documents the current
    // behaviour, not a requirement: the free list now holds `a` twice.
    pool.release(a);
    Tick* x = pool.allocate();
    Tick* y = pool.allocate();
    std::printf("note  double release with NDEBUG: %s\n",
                x == y ? "not detected, same slot handed out twice" : "detected");
    (void)b;
    return;
#endif
    pool.release(b);
}

static void release_foreign_pointers(){
    Pool<Tick, 4> pool;
    Pool<Tick, 4> other;
    Tick* held = pool.allocate();

    Tick on_stack{};
    EXPECT_REJECTED(pool, &on_stack);

    Tick* on_heap = new Tick{};
    EXPECT_REJECTED(pool, on_heap);
    delete on_heap;

    Tick* from_other = other.allocate();                  // a real slot, but of another pool
    EXPECT_REJECTED(pool, from_other);
    other.release(from_other);

    pool.release(held);
    CHECK(free_slots(pool) == 4);
    CHECK(free_slots(other) == 4);
}

static void release_just_outside_the_buffer(){
    Pool<Tick, 4> pool;
    const auto slots = all_slots(pool);
    Tick* held = pool.allocate();

    EXPECT_REJECTED(pool, at_offset(slots.front(), -static_cast<std::ptrdiff_t>(sizeof(Tick))));
    EXPECT_REJECTED(pool, at_offset(slots.front(), -1));
    EXPECT_REJECTED(pool, at_offset(slots.back(), sizeof(Tick)));     // one past the end
    EXPECT_REJECTED(pool, at_offset(slots.back(), sizeof(Tick) + 1));

    pool.release(held);
}

static void release_inside_a_slot(){
    Pool<Tick, 4> pool;
    const auto slots = all_slots(pool);
    Tick* held = pool.allocate();

    EXPECT_REJECTED(pool, at_offset(slots[1], 1));                    // misaligned
    EXPECT_REJECTED(pool, at_offset(slots[1], sizeof(Tick) / 2));     // aligned for int64, not a slot
    EXPECT_REJECTED(pool, at_offset(slots[1], sizeof(Tick) - 1));

    pool.release(held);
}

// Odd slot size: interior offsets are not multiples of a power of two.
struct Odd3{ char c[3]; };

static void release_inside_an_odd_slot(){
    Pool<Odd3, 4> pool;
    const auto slots = all_slots(pool);
    Odd3* held = pool.allocate();
    EXPECT_REJECTED(pool, at_offset(slots[0], 1));
    EXPECT_REJECTED(pool, at_offset(slots[0], 2));
    EXPECT_REJECTED(pool, at_offset(slots.back(), 3));                // one past the end
    pool.release(held);
}

static void rejected_release_keeps_the_object(){
    // A rejected release must not touch the pool's live objects.
    Pool<Tick, 4> pool;
    Tick* t = pool.allocate(Tick{42, 7, 3, 9, Operation::add, false});
    Tick on_stack{};
    EXPECT_REJECTED(pool, &on_stack);
    EXPECT_REJECTED(pool, at_offset(t, 1));
    CHECK(t->ts_ns == 42 && t->price == 7 && t->qty == 3 && t->order_id == 9);
    pool.release(t);
}

static void zero_capacity(){
    Pool<Tick, 0> pool;
    CHECK(pool.allocate() == nullptr);
    Tick on_stack{};
    EXPECT_REJECTED(pool, &on_stack);
    EXPECT_REJECTED(pool, static_cast<Tick*>(nullptr));
}

// ---------------------------------------------------------------------------
// 3. Alignment
// ---------------------------------------------------------------------------

struct B1{ char c; };
struct B12{ std::int32_t a, b, c; };                      // size 12, alignment 4
struct alignas(16) A16{ double d; };
struct alignas(64) A64{ std::int64_t v; };                // one cache line
struct alignas(128) A128{ std::int64_t v; };              // two cache lines (adjacent-line prefetch)
struct alignas(4096) A4096{ std::int64_t v; };            // one page

// Every slot is aligned for T, slots are sizeof(T) apart, and writing one never touches another.
template <typename T, std::size_t N>
static void check_layout(const char* name){
    Pool<T, N> pool;
    const auto slots = all_slots(pool);
    bool ok = slots.size() == N;

    for (std::size_t i = 0; i < slots.size(); ++i){
        ok &= addr(slots[i]) % alignof(T) == 0;
        if (i > 0)
            ok &= addr(slots[i]) - addr(slots[i - 1]) == sizeof(T);
    }

    std::vector<T*> held;
    while (T* p = pool.allocate())
        held.push_back(p);
    for (std::size_t i = 0; i < held.size(); ++i){
        auto* bytes = reinterpret_cast<unsigned char*>(held[i]);
        std::fill(bytes, bytes + sizeof(T), static_cast<unsigned char>(i + 1));
    }
    for (std::size_t i = 0; i < held.size(); ++i){
        auto* bytes = reinterpret_cast<unsigned char*>(held[i]);
        ok &= std::all_of(bytes, bytes + sizeof(T),
                          [&](unsigned char b){ return b == static_cast<unsigned char>(i + 1); });
    }
    for (T* p : held)
        pool.release(p);

    if (!ok)
        ++failures;
    std::printf("%s  layout %-6s size %-5zu align %-5zu x %zu\n",
                ok ? "ok  " : "FAIL", name, sizeof(T), alignof(T), N);
}

template <typename T>
static void check_layout_sizes(const char* name){
    check_layout<T, 1>(name);
    check_layout<T, 7>(name);                             // odd count
    check_layout<T, 64>(name);
}

// An over-aligned type: a pointer aligned for the members but not for T must be rejected.
static void release_under_aligned_pointer(){
    Pool<A64, 4> pool;
    const auto slots = all_slots(pool);
    A64* held = pool.allocate();
    EXPECT_REJECTED(pool, at_offset(slots[1], 8));        // aligned for int64, not for A64
    EXPECT_REJECTED(pool, at_offset(slots[1], 32));
    pool.release(held);
}

int main(){
#ifdef NDEBUG
    std::printf("pool regression (NDEBUG: bad releases must be ignored)\n");
#else
    std::printf("pool regression (asserts on: bad releases must abort)\n");
#endif

    fill_and_drain();
    reuse_after_release();
    single_slot();
    forwards_constructor_args();
    throwing_constructor_keeps_slot();
    large_pool();
    random_against_model();
    std::printf("%s  allocation\n", failures ? "FAIL" : "ok  ");

    const int before_release = failures;
    release_first_and_last_slot();
    release_nullptr();
    release_when_nothing_allocated();
    double_release();
    release_foreign_pointers();
    release_just_outside_the_buffer();
    release_inside_a_slot();
    release_inside_an_odd_slot();
    rejected_release_keeps_the_object();
    zero_capacity();
    release_under_aligned_pointer();
    std::printf("%s  release edge cases\n", failures > before_release ? "FAIL" : "ok  ");

    check_layout_sizes<B1>("B1");
    check_layout_sizes<Odd3>("Odd3");
    check_layout_sizes<B12>("B12");
    check_layout_sizes<Tick>("Tick");
    check_layout_sizes<A16>("A16");
    check_layout_sizes<A64>("A64");
    check_layout_sizes<A128>("A128");
    check_layout_sizes<A4096>("A4096");

    if (failures){
        std::printf("pool regression: %d check(s) FAILED\n", failures);
        return EXIT_FAILURE;
    }
    std::printf("pool regression: PASSED\n");
    return EXIT_SUCCESS;
}
